INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'GetsuFumaDen: Undying Moon - Digital Deluxe Edition', 'GetsuFumaDen: Undying Moon Digital Deluxe Edition combines intense roguelike hack-and-slash action with a stunning dark fantasy world, brought to life through the stroke of traditional Japanese art. The Digital Deluxe Edition includes the following bonus contents. - A bonus game: The original "GetsuFumaDen": discover the original game with the guidebook, a newly added Quick Save feature, and an English localized Menu screen (in-game texts and the guidebook are in Japanese only)! - A gallery mode with following contents limited to the Digital Deluxe edition - Digital artbook: contains the game''s key arts, stage concept designs, character designs, and the lore from the game. - Mini-OST: contains 15 sound tracks from the game with its attractive atmosphere.' FROM games WHERE igdb_id = 199824 ON CONFLICT (game_id, language_code) DO NOTHING;
