INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Sqroma', 'Sqroma is a puzzle game where you have to dodge the colored enemies to reach the end. You''ll be able to make the enemies kill themself or become yourself colored and pass through them and their shots. The levels do not restart after each death, use it as an advantage to create a path using your own body to block annoying shots.' FROM games WHERE igdb_id = 186020 ON CONFLICT (game_id, language_code) DO NOTHING;
