INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Maze to the old castle', 'Journey through various types of mazes, forests, tree-mazes, mountains, cave-maze, castle ruins, amids natural life and see if thee can reach the old castle. Maze to the old castle seeks to a-maze relax challege as a oldschool casual logic path-finding maze solving game.' FROM games WHERE igdb_id = 195293 ON CONFLICT (game_id, language_code) DO NOTHING;
