INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Survival Quiz City', 'Survival Quiz City is a multiplayer Survival Quiz Action game where only your smarts and skills will help you survive! Players answer questions and divide into two groups: the winners (correct answers) and the losers (incorrect answers). Fight as a team to win each round and survive to become the winner! The game is set to shutdown on October 31st with the option to transfer data to the new Japanese only free-to-play version of the game launching on October 12th.' FROM games WHERE igdb_id = 144486 ON CONFLICT (game_id, language_code) DO NOTHING;
