INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Wekele Wordle', 'Worde, the addictive word-guessing game that challenges your vocabulary and deduction skills in just six attempts. Can you crack the code and find the hidden word? Guess the daily word in 6 tries, practice with unlimited words or create your own Worde! Now with 5 levels: 4, 5, 6, 7 & 8 letter words!' FROM games WHERE igdb_id = 329557 ON CONFLICT (game_id, language_code) DO NOTHING;
