INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Tropico 6: Next Gen Edition', 'In Tropico 6: Next Gen Edition, the streets of your island will be busier, the beaches and panoramic views will be more beautiful, and El Presidente''s eyes will be more watchful than ever. Players will also receive the DLC "The Llama of Wall Street" and the El Prez Pack, which contains one additional mission, new buildings, new customization options for your palace, outfits for El Prez and much more!' FROM games WHERE igdb_id = 191496 ON CONFLICT (game_id, language_code) DO NOTHING;
